package net.civeira.phylax.feature.observe.observeddashboard.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboard;

public interface ObservedDashboardCacheGateway {

  /**
   * @autogenerated CacheGatewayGenerator
   */
  void evict();

  /**
   * @autogenerated CacheGatewayGenerator
   * @param observedDashboard
   */
  void remove(ObservedDashboard observedDashboard);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param filter
   * @param cursor
   * @return
   */
  Optional<ObservedDashboardCached> retrieve(ObservedDashboardFilter filter,
      ObservedDashboardCursor cursor);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param filter
   * @param cursor
   * @param observedDashboards
   * @return
   */
  ObservedDashboardCached store(ObservedDashboardFilter filter, ObservedDashboardCursor cursor,
      List<ObservedDashboard> observedDashboards);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param observedDashboard
   */
  void update(ObservedDashboard observedDashboard);
}
